INSERT INTO `categories` (`id`, `name`, `details`, `thumbnail`, `banner`, `link`, `type`, `order`, `created_at`, `updated_at`, `parent_id`) VALUES
(1, 'LED Recessed Luminaire', 'Miro LED Recessed Luminaires bring together energy efficiency, visual comfort, and modern elegance. Designed for seamless integration, they deliver flicker-free illumination with high CRI for true-to-life colors. Whether adjustable or fixed, each luminaire ensures durable performance and refined aesthetics perfect for transforming residential, retail, or office interiors with precision lighting and lasting quality.', 'categories/thumbnails/HeKMSBOme5mJwtnyeSWpA0rYDj0iYDEBgvLSfwyq.png', NULL, 'http://localhost:8000/product-blog', 'indoor', 1, '2025-05-10 21:49:49', '2025-08-03 08:16:35', NULL),
(2, 'LED Modular Recessed Luminaire', 'dscsdc', 'categories/thumbnails/LP8NPDC0NXTfVGygbVNabCif5ehVbQNRF7YlMQ3J.png', NULL, NULL, 'indoor', 2, '2025-05-10 21:52:11', '2025-08-03 01:02:47', NULL),
(3, 'LED Surface Mounted Luminaire', 'Designed to blend seamlessly with your space, Miro’s Surface Luminaires adjustable and fixed that bring elegance, performance, and purpose-driven illumination to every corner.', 'categories/thumbnails/4gsiQmAzJ990WBv7C5ec1HPdqRHiGPHOoI5B2b4j.png', 'categories/banners/8wFnC8gLQcL78DRM5kpw9GtUCSx4lbu2E5BUViXA.png', NULL, 'indoor', 3, '2025-05-10 21:53:53', '2025-05-11 20:00:48', NULL),
(4, 'Track Luminaire', 'Miro Lighting offers high-CRI track systems—high-voltage, magnetic, wire, and mini—for stylish, flexible, and powerful lighting. Ideal for retail, office, and displays, with premium LED performance.', 'categories/thumbnails/ZecEgDYFUAMEfFXkzr7wwAdofgMld81WbUi0qP9l.png', 'categories/banners/DvuCgw1zwpmxWUxx0tP76Fr1am53RjWuiyFv7nl7.png', NULL, 'indoor', 4, '2025-05-10 21:56:59', '2025-05-10 22:37:42', NULL),
(5, 'LED Commercial Luminaire', 'Miro LED Recessed Luminaires provide energy-efficient, flicker-free lighting with high CRI for true color accuracy. Adjustable and durable, they seamlessly integrate into modern interiors.', 'categories/thumbnails/wEIEwjL2XcqihfXeeOT8o9JHSHfBPckRDsFFeZsl.png', 'categories/banners/pCuWDVwcDrXuNdKUUQlezTXxalUhvoUVNIqQpBei.png', NULL, 'indoor', 5, '2025-05-10 21:58:02', '2025-05-10 21:58:02', NULL),
